// Filtra o que a secretaria NAO atende. Sai vazio = execucao morre aqui.
//
// NAO canonicaliza telefone de proposito: manda o JID cru e deixa a Edge Function
// resolver com telefoneWaDeJid. A regra de telefone ja divergiu uma vez neste projeto
// justamente por ganhar uma copia dentro de um no do n8n, e essa copia descartou um
// cliente em silencio.
const b = $json.body ?? $json;
const d = b?.data ?? {};
const key = d.key ?? {};
const jid = key.remoteJid ?? '';

// fromMe: mensagem nossa (humano ou a propria agente) nao inicia atendimento.
if (key.fromMe) return [];
if (!jid || jid.endsWith('@g.us') || jid.endsWith('@broadcast') || jid === 'status@broadcast') return [];

const msg = d.message ?? {};
const texto = (msg.conversation ?? msg.extendedTextMessage?.text ?? '').trim();

// Audio, imagem e figurinha ficam de fora: a secretaria le texto. O que ela nao
// entende continua sendo atendido por humano, como sempre foi.
if (!texto) return [];

return [{ json: {
  jid,
  texto,
  message_id: key.id ?? '',
  chave: `secretaria:ultima:${jid}`,
  // Marca desta execucao. E o que o debounce compara la na frente.
  marca: String($execution.id),
} }];

// A conversa vai pro agente; PRECO e FRETE nao. Isso e proposital: o agente tem que
// buscar numero pelas tools, nunca receber de bandeja e nunca inventar. Se o dado
// chegasse pronto no prompt, nao daria pra saber se ele consultou ou chutou.
const ctx = $json;
const base = $('Extrair mensagem').first().json;

const conversa = (ctx.conversa ?? [])
  .map((m) => `${m.de === 'cliente' ? 'CLIENTE' : 'NOS'}: ${m.texto}`)
  .join('\n');

// O pedido vigente vai como FATO, separado da conversa. Sem isso o agente deduzia o
// pedido das 30 ultimas mensagens — que nao tem fronteira de tempo — e somava com o
// pedido do dia anterior (defeito de 21/08: pediu 2 kg, ela anotou 4 kg).
const pedido = ctx.pedido_atual
  ? `PEDIDO JA REGISTRADO (e o que vale; modifique ISTO): ${ctx.pedido_atual}`
  : 'PEDIDO JA REGISTRADO: nenhum. Nada do que aparecer na conversa acima conta como pedido em aberto.';

const entrada = [
  `Cliente: ${ctx.contato?.nome ?? 'sem nome'}`,
  '',
  pedido,
  '',
  'CONVERSA ATE AGORA:',
  conversa || '(primeira mensagem)',
  '',
  `ULTIMA MENSAGEM DO CLIENTE: ${base.texto}`,
  '',
  'Responda a ultima mensagem.',
].join('\n');

return [{ json: { entrada, jid: base.jid, message_id: base.message_id, nome: ctx.contato?.nome ?? null } }];

// Um item por mensagem a enviar, cada um com o proprio tempo de digitacao.
const prep = $('Preparar envio').first().json;
const jid = $('Extrair mensagem').first().json.jid;
const partes = prep.partes ?? [];
const tempos = prep.tempos_ms ?? [];

return partes.map((parte, i) => ({ json: {
  parte,
  tempo_ms: tempos[i] ?? 4000,
  jid,
  numero: jid.split('@')[0],
} }));

